fn r(p:impl AsRef<Path>)->PathBuf{Path::new(R).join(p)}fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}fn hash(b:&[u8])->String{format!("{:x}",Sha256::digest(b))}
fn walk(p:&Path)->Vec<PathBuf>{let mut v=vec![];for e in fs::read_dir(p).unwrap(){let p=e.unwrap().path();if p.is_dir(){v.extend(walk(&p));}else{v.push(p);}}v.sort();v}
